def nash_solver(R, C):
    nash_solver = {}

    for i in range(len(R)):
        for j in range(len(C)):
            max_in_col = max([R[k][j] for k in range(len(R))])
            max_in_row = max([C[i][l] for l in range(len(C))])

            if max_in_col == R[i][j] and max_in_row == C[i][j]:
                nash_solver[(i, j)] = (i, j)

    return next(iter(nash_solver.values()), None)
